  test("https-only-clean-base",()->{for(String base:Arrays.asList("http://127.0.0.1/","https://user:secret@example.test/","https://example.test/?token=x","https://example.test/#fragment","https://example.test/../path"))reject(()->new AegirSecurityClient(base,null,null));});
