  test("concrete-client-policy-clone-keeps-caller-unchanged",()->{HttpClient original=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.ALWAYS).connectTimeout(Duration.ofSeconds(60)).build();try(AegirSecurityClient c=new AegirSecurityClient("https://example.test",null,null,original)){java.lang.reflect.Field field=AegirSecurityClient.class.getDeclaredField("httpClient");field.setAccessible(true);HttpClient owned=(HttpClient)field.get(c);check(original.followRedirects()==HttpClient.Redirect.ALWAYS&&owned!=original&&owned.followRedirects()==HttpClient.Redirect.NEVER&&owned.connectTimeout().get().compareTo(Duration.ofSeconds(30))<=0,"Caller mutated or unsafe policy reused");}});
