  test("strict-json-media-type",()->{try(Fixture f=new Fixture()){f.media="application/jsonp";try(AegirSecurityClient c=f.client()){reject(()->c.getIdentityGraph("developer:dev_123"));}}});
  test("unsupported-json-charset",()->{try(Fixture f=new Fixture()){f.media="application/json; charset=iso-8859-1";try(AegirSecurityClient c=f.client()){reject(()->c.getIdentityGraph("developer:dev_123"));}}});
  test("malformed-utf8-denied",()->{try(Fixture f=new Fixture()){f.invalidUtf8=true;try(AegirSecurityClient c=f.client()){reject(()->c.getIdentityGraph("developer:dev_123"));}}});
