  test("sanitized-errors-and-diagnostics",()->{try(Fixture f=new Fixture()){f.status=403;f.body="{\"error\":\"synthetic-upstream-secret\",\"message\":\"synthetic-developer-key\"}";f.correlation="synthetic-developer-key";List<AegirDiagnosticsHooks.LogEntry>logs=new ArrayList<>();List<AegirDiagnosticsHooks.TraceEvent>traces=new ArrayList<>();try(AegirSecurityClient c=AegirSecurityClient.pinnedLoopbackDevelopment(f.base,"synthetic-developer-key",f.pin,Duration.ofSeconds(2),new AegirDiagnosticsHooks(logs::add,null,traces::add))){try{c.reverseAction("private-action","private-reason");throw new AssertionError("Error absent");}catch(AegirSecurityError e){check(e.getBody()==null&&e.getCorrelationId()==null&&"forbidden".equals(e.getCode())&&e.getCause()==null,"Upstream values exposed");}String text=logs.toString()+traces.toString()+c.toString();check(!text.contains("private-action")&&!text.contains("private-reason")&&!text.contains("synthetic-developer-key")&&!text.contains("synthetic-upstream-secret"),"Diagnostic values exposed");}}});
