  test("credential-secret-component-not-a-correlation-id",()->{try(Fixture f=new Fixture()){f.status=403;f.body="{\"error\":\"forbidden\"}";f.correlation="corr-synthetic-private-component";try(AegirSecurityClient c=AegirSecurityClient.pinnedLoopbackDevelopment(f.base,"dev_key_id:synthetic-private-component",f.pin,Duration.ofSeconds(1),null)){try{c.getIdentityGraph("developer:dev_123");throw new AssertionError("Error absent");}catch(AegirSecurityError e){check(e.getCorrelationId()==null,"Secret component leaked");}}}});
  test("canonical-numeric-enums-normalize-all-six-types",()->{try(Fixture f=new Fixture()){f.body="{\"subjectId\":\"developer:dev_123\",\"graph\":{\"graphId\":\"graph:developer:dev_123\",\"generatedAtUtc\":\"2026-04-07T15:00:00Z\",\"scores\":{\"exposureScore\":0.15,\"trustScore\":0.92,\"connectionClarityScore\":0.88},\"nodes\":[{\"nodeId\":\"developer:dev_123\",\"nodeType\":6,\"displayName\":\"dev_123@example.com\",\"status\":\"active\",\"trustTier\":\"high\",\"observedAtUtc\":\"2026-04-07T15:00:00Z\",\"lastVerifiedAtUtc\":null,\"metadata\":{}}],\"edges\":[{\"edgeId\":\"edge:one\",\"edgeType\":1,\"fromNodeId\":\"developer:dev_123\",\"toNodeId\":\"app:one\",\"status\":\"active\",\"trustWeight\":0.5,\"evidenceType\":\"registration\",\"reason\":\"synthetic\",\"observedAtUtc\":\"2026-04-07T15:00:00Z\",\"lastVerifiedAtUtc\":null,\"metadata\":{}}],\"metadata\":{}},\"exposure\":{\"graphId\":\"graph:developer:dev_123\",\"generatedAtUtc\":\"2026-04-07T15:00:00Z\",\"exposureScore\":0.15,\"findings\":[{\"findingId\":\"finding_001\",\"category\":1,\"severity\":2,\"summary\":\"Weak service linkage.\",\"nodeId\":\"developer:dev_123\",\"edgeId\":null,\"metadata\":{}}],\"summaryText\":\"Low exposure posture.\"},\"actionHistory\":[{\"actionId\":\"action_001\",\"subjectId\":\"developer:dev_123\",\"actionType\":3,\"status\":1,\"targetNodeId\":\"application:app_portal\",\"reason\":\"Go sample validation.\",\"requestedAtUtc\":\"2026-04-07T15:00:00Z\",\"reversedAtUtc\":null,\"reverseReason\":null,\"metadata\":{}}]}";try(AegirSecurityClient c=f.client()){SecurityModels.ScanIdentityResult scan=c.scanIdentity("developer:dev_123");check(scan.getGraph().getNodes().get(0).getNodeType()==SecurityModels.IdentityGraphNodeType.User&&scan.getGraph().getEdges().get(0).getEdgeType()==SecurityModels.IdentityGraphEdgeType.Owns&&scan.getExposure().getFindings().get(0).getSeverity()==SecurityModels.ExposureFindingSeverity.Medium&&scan.getActionHistory().get(0).getActionType()==SecurityModels.IdentityActionType.VerifyConnection,"Canonical enums not normalized");}}});
  test("numeric-enums-only-known-exact-integers",()->{for(String name:Arrays.asList("IdentityActionType","IdentityActionStatus","IdentityGraphNodeType","IdentityGraphEdgeType","ExposureFindingCategory","ExposureFindingSeverity")){check(LegacyContracts.enumName(Long.valueOf(1),name) instanceof String,"Known enum rejected");for(Object badEnum:Arrays.asList(Long.valueOf(0),Long.valueOf(999),new java.math.BigDecimal("1.0"),"1","Unknown",true))reject(()->LegacyContracts.enumName(badEnum,name));}});
