  test("atomic-replace-windows-retry-and-exhaustion-bounded",()->{java.util.concurrent.atomic.AtomicLong clock=new java.util.concurrent.atomic.AtomicLong();AtomicInteger calls=new AtomicInteger();FileAuthorizationJournal.atomicReplaceWith(()->{if(calls.incrementAndGet()==1)throw new java.nio.file.AccessDeniedException("synthetic-temp");},true,clock::get,millis->clock.addAndGet(millis*1000000));check(calls.get()==2,"Transient replace not retried");calls.set(0);long start=clock.get();reject(()->FileAuthorizationJournal.atomicReplaceWith(()->{calls.incrementAndGet();throw new java.nio.file.AccessDeniedException("synthetic-temp");},true,clock::get,millis->clock.addAndGet(millis*1000000)));check(calls.get()<=22&&clock.get()-start<=200000000L,"Retry exceeded bound");calls.set(0);reject(()->FileAuthorizationJournal.atomicReplaceWith(()->{calls.incrementAndGet();throw new IOException("nonsharing");},true,clock::get,millis->{throw new AssertionError("Nonsharing failure retried");}));check(calls.get()==1,"Nonsharing error changed");});
  test("raw-developer-user-numeric-graph-and-exposure-binding",()->{for(String kind:Arrays.asList("developer","user")){try(Fixture f=new Fixture()){String subject="raw-"+kind+"-id",graphId="graph:"+kind+":"+subject;Map<String,Object>graph=IntegrationJson.object(IntegrationJson.parse(GRAPH));graph.put("graphId",graphId);Map<String,Object>node=new LinkedHashMap<>();node.put("nodeId",kind+":"+subject);node.put("nodeType",kind.equals("developer")?2L:6L);node.put("displayName","Synthetic identity");node.put("status","active");node.put("trustTier","verified");node.put("observedAtUtc","2026-04-07T15:00:00Z");node.put("lastVerifiedAtUtc",null);node.put("metadata",Map.of());graph.put("nodes",List.of(node));f.body=IntegrationJson.stringify(graph);try(AegirSecurityClient c=f.client()){c.getIdentityGraph(subject);Map<String,Object>exposure=new LinkedHashMap<>();exposure.put("graphId",graphId);exposure.put("generatedAtUtc","2026-04-07T15:00:00Z");exposure.put("exposureScore",new java.math.BigDecimal("0.1"));exposure.put("findings",List.of());exposure.put("summaryText","Synthetic");f.body=IntegrationJson.stringify(exposure);c.getExposureSummary(subject);exposure.put("graphId","graph:"+kind+":unrelated-id");f.body=IntegrationJson.stringify(exposure);reject(()->c.getExposureSummary(subject));graph.put("graphId","graph:"+kind+":unrelated-id");f.body=IntegrationJson.stringify(graph);reject(()->c.getIdentityGraph(subject));}}}});
  test("deadline-close-cancellation-and-thread-disposal",LegacySecurityHardeningTest::cancellation);
