 static void cancellation()throws Exception{for(String mode:Arrays.asList("deadline","close","interrupt")){try(Fixture f=new Fixture()){f.block=true;try(AegirSecurityClient c=AegirSecurityClient.pinnedLoopbackDevelopment(f.base,null,f.pin,Duration.ofMillis(200),null)){AtomicBoolean denied=new AtomicBoolean();Thread worker=new Thread(()->{try{c.getIdentityGraph("developer:dev_123");}catch(Exception expected){denied.set(true);}});worker.start();check(f.entered.await(2,TimeUnit.SECONDS),"Fixture not reached");long started=System.nanoTime();if(mode.equals("close"))c.close();if(mode.equals("interrupt"))worker.interrupt();worker.join(1500);check(!worker.isAlive()&&denied.get()&&System.nanoTime()-started<1500000000L,"Unbounded request or false result");if(mode.equals("close"))reject(()->c.getIdentityGraph("developer:dev_123"));}}}Thread.sleep(100);for(Thread t:Thread.getAllStackTraces().keySet())check(!t.isAlive()||!t.getName().equals("aegir-security-transport"),"Owned transport thread leaked");}
 // This adapter is synthetic trusted host code. Its successful DTO is not real-server authority.
 static final class OpaqueClient extends HttpClient{
  final HttpClient delegate=HttpClient.newHttpClient();
  public Optional<CookieHandler>cookieHandler(){return delegate.cookieHandler();}public Optional<Duration>connectTimeout(){return delegate.connectTimeout();}public Redirect followRedirects(){return delegate.followRedirects();}public Optional<ProxySelector>proxy(){return delegate.proxy();}public SSLContext sslContext(){return delegate.sslContext();}public SSLParameters sslParameters(){return delegate.sslParameters();}public Optional<java.net.Authenticator>authenticator(){return delegate.authenticator();}public Version version(){return delegate.version();}public Optional<Executor>executor(){return delegate.executor();}
  public <T>HttpResponse<T>send(HttpRequest r,HttpResponse.BodyHandler<T>b)throws IOException,InterruptedException{try{return sendAsync(r,b).get();}catch(ExecutionException e){throw new IOException("Synthetic adapter failed.");}}
  @SuppressWarnings("unchecked")public <T>CompletableFuture<HttpResponse<T>>sendAsync(HttpRequest r,HttpResponse.BodyHandler<T>b){return CompletableFuture.completedFuture(new HttpResponse<T>(){public int statusCode(){return 200;}public HttpRequest request(){return r;}public Optional<HttpResponse<T>>previousResponse(){return Optional.empty();}public HttpHeaders headers(){return HttpHeaders.of(Map.of("Content-Type",List.of("application/json")),(a,c)->true);}public T body(){return(T)GRAPH.getBytes(StandardCharsets.UTF_8);}public Optional<SSLSession>sslSession(){return Optional.empty();}public URI uri(){return r.uri();}public Version version(){return Version.HTTP_1_1;}});}
  public <T>CompletableFuture<HttpResponse<T>>sendAsync(HttpRequest r,HttpResponse.BodyHandler<T>b,HttpResponse.PushPromiseHandler<T>p){return sendAsync(r,b);}
 }
